/**
 * Authoritative Queued replace — do not mergeJobUpdate with stale Pending/U-A store rows.
 * Preserves passenger fields from prior when Firebase partial is thin, but status/driver
 * always come from the Queued authority (refresh or allbookings).
 */
function applyQueueAuthoritativeReplace(
  prior: Job | null,
  job: Job,
  refreshDriverId?: string | null,
): Job {
  const refreshDrv =
    refreshDriverId != null && String(refreshDriverId).trim() !== ''
      ? String(refreshDriverId).trim()
      : '';
  const jobDrv = job.driverId != null ? String(job.driverId).trim() : '';
  const priorDrv = prior?.driverId != null ? String(prior.driverId).trim() : '';
  const driverId = !isUnassignedDriverId(refreshDrv)
    ? refreshDrv
    : !isUnassignedDriverId(jobDrv)
      ? jobDrv
      : !isUnassignedDriverId(priorDrv)
        ? priorDrv
        : jobDrv || priorDrv || undefined;
  const vehicleId = job.vehicleId ?? prior?.vehicleId;
  const base = prior ?? job;
  return {
    ...base,
    status: 'Queued',
    driverId,
    vehicleId,
    ...(job.updateSeq != null
      ? { updateSeq: Math.max(base.updateSeq ?? 0, job.updateSeq) }
      : {}),
  };
}

type TerminalRefreshDebug = {
  action?: string;
  status?: string;
  caller: string;
  at?: number;
  terminalAt?: number;
};

/** Live statuses that must not reappear on Assign after a terminal dispatchConsole refresh. */
const STALE_GUARD_LIVE_STATUSES = new Set<JobStatus>(['Arrived', 'Assigned']);

/**
 * Per-booking terminal authority from dispatchConsole/{cid}/refresh.
 * Ignores stale live Arrived/Assigned hints that predate (or share the same
 * updateSeq generation as) the last terminal signal for this bookingId.
 */
const lastTerminalAtByBookingId = new Map<
  number,
  { terminalAt: number; updateSeq: number }
>();

function recordTerminalRefreshGuard(
  bookingId: number,
  opts: { at?: number; terminalAt?: number; updateSeq?: number; source?: string },
): void {
  if (!bookingId) return;
  const terminalAt = Math.max(opts.terminalAt ?? 0, opts.at ?? 0) || Date.now();
  const prev = lastTerminalAtByBookingId.get(bookingId);
  const next = {
    terminalAt: Math.max(prev?.terminalAt ?? 0, terminalAt),
    updateSeq: Math.max(prev?.updateSeq ?? 0, opts.updateSeq ?? 0),
  };
  lastTerminalAtByBookingId.set(bookingId, next);
  console.log('[dispatch-terminal] lastTerminalAt set', {
    bookingId,
    source: opts.source ?? 'unknown',
    signalAt: opts.at ?? null,
    signalTerminalAt: opts.terminalAt ?? null,
    resolvedTerminalAt: next.terminalAt,
    updateSeq: next.updateSeq,
    previousTerminalAt: prev?.terminalAt ?? null,
    previousUpdateSeq: prev?.updateSeq ?? 0,
  });
}

/** True when a live refresh must be dropped after terminal was already applied. */
function shouldIgnoreStaleLiveDispatchRefresh(
  bookingId: number,
  refresh: DispatchRefreshPayload,
  signalAt: number,
): boolean {
  const guard = lastTerminalAtByBookingId.get(bookingId);
  if (!guard) return false;

  const status = refresh.status ? normalizeJobStatus(refresh.status) : null;
  if (!status || !STALE_GUARD_LIVE_STATUSES.has(status)) return false;

  const refreshSeq = refresh.updateSeq ?? 0;
  // Booking id reused — server advanced past the terminal generation.
  if (refreshSeq > guard.updateSeq && refreshSeq > 0) {
    console.log('[dispatch-terminal] live refresh allowed (seq reuse)', {
      bookingId,
      status,
      action: refresh.action ?? null,
      signalAt: signalAt || null,
      refreshSeq,
      guardTerminalAt: guard.terminalAt,
      guardUpdateSeq: guard.updateSeq,
    });
    return false;
  }

  console.log('[dispatch-terminal] ignored stale live dispatchConsole/refresh', {
    bookingId,
    action: refresh.action ?? null,
    status,
    signalAt: signalAt || null,
    refreshUpdateSeq: refreshSeq,
    lastTerminalAt: guard.terminalAt,
    lastTerminalUpdateSeq: guard.updateSeq,
    reason: signalAt > 0 && signalAt < guard.terminalAt
      ? 'signalAt_lt_terminalAt'
      : 'post_terminal_live_status',
  });
  return true;
}

/** Block stale Arrived/Assigned rows in allbookings after terminal authority is recorded. */
function shouldSkipStaleLiveAllbookingsIngest(
  jobId: number,
  effectiveStatus: JobStatus,
  rec: Record<string, unknown>,
): boolean {
  const guard = lastTerminalAtByBookingId.get(jobId);
  if (!guard) return false;
  if (!STALE_GUARD_LIVE_STATUSES.has(effectiveStatus)) return false;
  const fbSeq = seqFromFirebaseRecord(rec) ?? 0;
  if (fbSeq > guard.updateSeq && fbSeq > 0) return false;
  console.log('[dispatch-terminal] skipped stale live allbookings ingest', {
    bookingId: jobId,
    effectiveStatus,
    fbSeq,
    lastTerminalAt: guard.terminalAt,
    lastTerminalUpdateSeq: guard.updateSeq,
  });
  return true;
}

function handleTerminalRefresh(
  bookingId: number,
  pendingRef: Map<number, Job>,
  bookingsRef: Map<number, Job>,
  removeJob: (id: number) => void,
  syncAll: () => void,
  suppressSeq = 0,
  debug?: TerminalRefreshDebug,
): void {
  recordTerminalRefreshGuard(bookingId, {
    at: debug?.at,
    terminalAt: debug?.terminalAt,
    updateSeq: suppressSeq,
    source: debug?.caller ?? 'handleTerminalRefresh',
  });
  const storeJob = useJobStore.getState().jobs.find((j) => j.id === bookingId);
  console.log('[dispatch-terminal] handleTerminalRefresh', {
    bookingId,
    action: debug?.action ?? null,
    status: debug?.status ?? null,
    caller: debug?.caller ?? 'unknown',
    suppressSeq,
    hadInBookings: bookingsRef.has(bookingId),
    hadInPending: pendingRef.has(bookingId),
    storeHad: !!storeJob,
    storeStatus: storeJob?.status ?? null,
    blacklisted: useJobStore.getState().isJobBlacklisted(bookingId),
  });
  pendingRef.delete(bookingId);
  bookingsRef.delete(bookingId);
  markCompletedJobSuppress(bookingId, suppressSeq);
  clearQueueAwaitingAllbookings(bookingId);
  clearOfferAwaitingAllbookings(bookingId);
  clearOptimisticLiveTransition(bookingId);
  removeJob(bookingId);
  syncAll();
}

function mergeJobs(maps: Map<number, Job>[]): Job[] {
  const byId = new Map<number, Job>();
  for (const m of maps) {
    for (const [id, job] of m) {
      const prev = byId.get(id);
      const opts = queueAwaitingMergeOpts(id);
      byId.set(id, prev ? mergeJobUpdate(prev, job, opts) : opts ? mergeJobUpdate(job, { status: 'Queued' }, opts) : job);
    }
  }
  return Array.from(byId.values());
}

function traceAllbookingsIngest(
  jobId: number,
  reason: string,
  detail: Record<string, unknown>,
) {
  if (!DISPATCH_QUEUE_TRACE_IDS.has(jobId)) return;
  console.log(`[dispatch-queue-debug] allbookings ${reason}`, { jobId, ...detail });
}

function isBlacklisted(jobId: number): boolean {
  return useJobStore.getState().isJobBlacklisted(jobId);
}

/** Purge cancelled job from in-memory listener caches so it cannot reappear. */
export function purgeCancelledJobFromListeners(jobId: number) {
  listenerPendingCache?.delete(jobId);
  listenerBookingsCache?.delete(jobId);
}

/** Drop a terminal/cancelled job from dispatch listeners and blacklist re-ingest. */
export function purgeDispatchTerminalJob(jobId: number, suppressSeq = 0) {
  markCompletedJobSuppress(jobId, suppressSeq);
  clearQueueAwaitingAllbookings(jobId);
  clearOfferAwaitingAllbookings(jobId);
  purgeCancelledJobFromListeners(jobId);
  useJobStore.getState().removeJob(jobId);
}

