type DispatchFirebaseAuthCtx = {
  uid: string | null;
  isAnonymous: boolean;
  adminAccessExists: boolean | null;
};

async function bootstrapDispatchFirebaseAccess(companyId: string): Promise<DispatchFirebaseAuthCtx> {
  const user = getFirebaseAuth().currentUser;
  const ctx: DispatchFirebaseAuthCtx = {
    uid: user?.uid ?? null,
    isAnonymous: !!user?.isAnonymous,
    adminAccessExists: null,
  };
  if (!user) {
    console.warn(
      '[dispatch-queue-debug] no Firebase auth user — allbookings onValue may return a rules-filtered subset (sign in via /login)',
    );
    return ctx;
  }
  if (user.isAnonymous) {
    console.warn(
      '[dispatch-queue-debug] anonymous Firebase auth — adminAccess will not match; allbookings Queued rows for assigned drivers are omitted by RTDB rules',
      { uid: user.uid, companyId },
    );
    return ctx;
  }
  try {
    await ensureAdminAccess(companyId, user.uid);
  } catch (e) {
    console.warn('[dispatch-queue-debug] ensure-admin-access failed', e);
  }
  try {
    const adminSnap = await get(ref(getDb(), `adminAccess/${companyId}/${user.uid}`));
    ctx.adminAccessExists = adminSnap.exists();
    console.log('[dispatch-queue-debug] adminAccess probe', {
      companyId,
      uid: user.uid,
      adminAccessExists: ctx.adminAccessExists,
    });
    if (!ctx.adminAccessExists) {
      console.warn(
        '[dispatch-queue-debug] adminAccess node missing — per-child allbookings rules will filter to driver-assigned rows only',
      );
    }
  } catch (e) {
    console.warn('[dispatch-queue-debug] adminAccess probe failed', e);
  }
  return ctx;
}

function logAllbookingsSnapshotSummary(
  companyId: string,
  authCtx: DispatchFirebaseAuthCtx,
  val: unknown,
  seenInSnapshot: Set<number>,
): void {
  const rawKeys =
    val && typeof val === 'object' ? Object.keys(val as Record<string, unknown>) : [];
  const queuedInSnapshot: number[] = [];
  const pendingInSnapshot: number[] = [];
  if (val && typeof val === 'object') {
    for (const [key, rec] of Object.entries(val as Record<string, Record<string, unknown>>)) {
      const jobId = parseInt(String(rec.BookingId ?? rec.bookingId ?? key), 10);
      if (!jobId) continue;
      const st = normalizeJobStatus(
        String(rec.BookingStatus ?? rec.bookingStatus ?? rec.Status ?? rec.status ?? ''),
      );
      if (st === 'Queued') queuedInSnapshot.push(jobId);
      if (st === 'Pending' || st === 'No One') pendingInSnapshot.push(jobId);
    }
  }
  const tracePresence: Record<string, boolean> = {};
  for (const id of DISPATCH_QUEUE_TRACE_IDS) {
    tracePresence[String(id)] = seenInSnapshot.has(id);
  }
  console.log('[dispatch-queue-debug] allbookings onValue snapshot', {
    companyId,
    firebaseUid: authCtx.uid,
    firebaseIsAnonymous: authCtx.isAnonymous,
    adminAccessExists: authCtx.adminAccessExists,
    snapshotRawChildCount: rawKeys.length,
    snapshotParsedJobCount: seenInSnapshot.size,
    queuedInSnapshotCount: queuedInSnapshot.length,
    queuedInSnapshotIds: queuedInSnapshot.slice(0, 40),
    pendingInSnapshotCount: pendingInSnapshot.length,
    tracePresence,
    note:
      'RTDB applies per-child .read rules on parent onValue — count can be lower than server jobStore when adminAccess is missing',
  });
}

type MergeTraceCtx = {
  pendingRef: Map<number, Job>;
  bookingsRef: Map<number, Job>;
  storeJobs: Job[];
  mergedPreFilter: Job[];
  mergedPostFilter: Job[];
  byId: Map<number, Job>;
  removed: Set<number>;
};

function mergeTraceRow(id: number, ctx: MergeTraceCtx) {
  const pending = ctx.pendingRef.get(id);
  const booking = ctx.bookingsRef.get(id);
  const store = ctx.storeJobs.find((j) => j.id === id);
  const pre = ctx.mergedPreFilter.find((j) => j.id === id);
  const postFilter = ctx.mergedPostFilter.find((j) => j.id === id);
  const final = ctx.byId.get(id);
  return {
    id,
    blacklisted: ctx.removed.has(id),
    queueAwaiting: isQueueAwaitingAllbookings(id),
    pendingStatus: pending?.status ?? null,
    pendingUpdateSeq: pending?.updateSeq ?? null,
    bookingsStatus: booking?.status ?? null,
    bookingsUpdateSeq: booking?.updateSeq ?? null,
    storeStatus: store?.status ?? null,
    storeUpdateSeq: store?.updateSeq ?? null,
    afterMergeJobsStatus: pre?.status ?? null,
    afterBlacklistFilterStatus: postFilter?.status ?? null,
    finalStatus: final?.status ?? null,
    finalTab: final ? jobTabForStatus(final) : null,
    preservedFromStoreOnly: !pending && !booking && !!store && !!final,
  };
}

function logSyncAllMergePipeline(ctx: MergeTraceCtx) {
  const allIds = new Set<number>([
    ...ctx.pendingRef.keys(),
    ...ctx.bookingsRef.keys(),
    ...ctx.storeJobs.map((j) => j.id),
    ...ctx.byId.keys(),
    ...DISPATCH_QUEUE_TRACE_IDS,
  ]);
  const rows = [...allIds].sort((a, b) => a - b).map((id) => mergeTraceRow(id, ctx));
  const shouldLog =
    ctx.byId.size > 0 ||
    [...DISPATCH_QUEUE_TRACE_IDS].some(
      (id) =>
        ctx.pendingRef.has(id) ||
        ctx.bookingsRef.has(id) ||
        ctx.storeJobs.some((j) => j.id === id) ||
        ctx.byId.has(id),
    );
  if (!shouldLog) return;
  console.log('[dispatch-queue-debug] syncAll merge pipeline', {
    mergedCount: ctx.byId.size,
    bookingsRefSize: ctx.bookingsRef.size,
    pendingRefSize: ctx.pendingRef.size,
    removedBlacklist: [...ctx.removed],
    rows,
    focus: [...DISPATCH_QUEUE_TRACE_IDS].map((id) => mergeTraceRow(id, ctx)),
    allJobsFinal: [...ctx.byId.values()].map((j) => ({
      id: j.id,
      status: j.status,
      normalizedStatus: normalizeJobStatus(j.status),
      tab: jobTabForStatus(j),
      driverId: j.driverId,
      updateSeq: j.updateSeq ?? null,
    })),
  });
}

type DispatchRefreshPayload = {
  action?: string;
  status?: string;
  driverId?: string;
  declinedDriverId?: string;
  returnReason?: string;
  updateSeq?: number;
  at?: number;
  terminalAt?: number;
};

function notifyOfferReturned(bookingId: number, refresh: DispatchRefreshPayload) {
  const action = refresh.action;
  if (action !== 'timeout' && action !== 'decline') return;
  const drv = String(refresh.declinedDriverId || refresh.driverId || '').trim();
  const who = drv && drv !== '0' ? `Driver ${drv}` : 'Driver';
  const verb = action === 'timeout' ? 'did not respond to' : 'declined';
  useUiStore.getState().addToast({
    type: 'warning',
    title: `Offer returned — job #${bookingId}`,
    message: `${who} ${verb} job #${bookingId} — returned to pending.`,
    category: 'general',
  });
}

const POOL_RESTORE_ACTIONS = new Set(['status', 'timeout', 'decline', 'recall', 'scheduled_release']);

function refreshTrustsPoolRestore(
  refresh: DispatchRefreshPayload,
  fbSeq: number | null | undefined,
): boolean {
  if (!refresh.status || !POOL_RESTORE_ACTIONS.has(refresh.action || '')) return false;
  const target = normalizeJobStatus(refresh.status);
  if (target !== 'Pending' && target !== 'No One' && target !== 'Scheduled') return false;
  const hintSeq = refresh.updateSeq ?? 0;
  if (hintSeq > 0 && fbSeq != null && hintSeq >= fbSeq) return true;
  return POOL_RESTORE_ACTIONS.has(refresh.action || '');
}

function pendingjobsAbsentIsPoolRestore(
  job: Job | null,
  refresh: DispatchRefreshPayload,
): boolean {
  if (!job) return false;
  if (!isPoolUaStatus(job.status)) return false;
  if (POOL_RESTORE_ACTIONS.has(refresh.action || '')) return true;
  return normalizeJobStatus(refresh.status || '') === normalizeJobStatus(job.status);
}

function pendingSnapshotWouldRegressPool(
  refresh: DispatchRefreshPayload,
  pjVal: Record<string, unknown>,
): boolean {
  if (!refresh.status) return false;
  const target = normalizeJobStatus(refresh.status);
  if (target !== 'Pending' && target !== 'No One') return false;
  if (!POOL_RESTORE_ACTIONS.has(refresh.action || '')) return false;
  const pjSt = normalizeJobStatus(String(pjVal.BookingStatus ?? pjVal.Status ?? pjVal.status ?? ''));
  return LIVE_OFFER_STATUSES.has(pjSt);
}

function seqFromFirebaseRecord(rec: Record<string, unknown> | null | undefined): number | undefined {
  if (!rec || typeof rec !== 'object') return undefined;
  const raw = rec.updateSeq ?? rec._seq ?? rec.version;
  const n = parseInt(String(raw ?? ''), 10);
  return Number.isNaN(n) ? undefined : n;
}

function resolveRefreshDriverId(
  refresh: DispatchRefreshPayload,
  targetStatus: Job['status'],
  job: Job | null,
  prior: Job | null,
): string {
  if (targetStatus === 'No One') return '-1';
  if (targetStatus === 'Pending') {
    if (POOL_RESTORE_ACTIONS.has(refresh.action || '')) return '0';
    if (refresh.driverId === '0' || refresh.driverId === '') return '0';
  }
  if (refresh.driverId !== undefined && refresh.driverId !== null && refresh.driverId !== '') {
    return String(refresh.driverId);
  }
  return job?.driverId ?? prior?.driverId ?? '0';
}

function existingJobSnapshot(
  bookingId: number,
  pendingRef: Map<number, Job>,
  bookingsRef: Map<number, Job>,
): Job | null {
  return (
    bookingsRef.get(bookingId) ??
    pendingRef.get(bookingId) ??
    useJobStore.getState().jobs.find((j) => j.id === bookingId) ??
    null
  );
}

function priorTerminalSuppressSeq(
  bookingId: number,
  pendingRef: Map<number, Job>,
  bookingsRef: Map<number, Job>,
): number {
  const prior = existingJobSnapshot(bookingId, pendingRef, bookingsRef);
  return prior?.updateSeq ?? 0;
}

function refreshImpliesTerminal(refresh: DispatchRefreshPayload): boolean {
  if (
    refresh.action === 'cancel' ||
    refresh.action === 'no-show' ||
    refresh.action === 'complete'
  ) {
    return true;
  }
  if (!refresh.status) return false;
  return TERMINAL_BOOKING_STATUSES.has(normalizeJobStatus(refresh.status));
}

function terminalRefreshDebug(
  refresh: DispatchRefreshPayload,
  caller: string,
): TerminalRefreshDebug {
  return {
    action: refresh.action,
    status: refresh.status,
    caller,
    at: refresh.at,
    terminalAt: refresh.terminalAt,
  };
}

function applyRefreshStatusHint(
  job: Job | null,
  prior: Job | null,
  refresh: DispatchRefreshPayload,
  bookingId: number,
): Job | null {
  if (!refresh.status) return job;
  const targetStatus = normalizeJobStatus(refresh.status);
  // Terminal must never be merged into the live store — caller removes the job.
  if (TERMINAL_BOOKING_STATUSES.has(targetStatus)) {
    return null;
  }
  const driverId = resolveRefreshDriverId(refresh, targetStatus, job, prior);
  const updateSeq = refresh.updateSeq ?? job?.updateSeq ?? prior?.updateSeq;
  const patch = { status: targetStatus, driverId, ...(updateSeq != null ? { updateSeq } : {}) } as Job;

  // Queued + real driver: REPLACE (no mergeJobUpdate) so stale Pending cannot win.
  if (targetStatus === 'Queued' && !isUnassignedDriverId(driverId)) {
    const base = job ?? prior;
    if (!base && useJobStore.getState().isJobBlacklisted(bookingId)) return null;
    return applyQueueAuthoritativeReplace(base, { ...(base ?? { id: bookingId } as Job), ...patch }, refresh.driverId);
  }

  const queueOpts = refresh.action === 'queue' ? ({ forceStatus: 'Queued' as JobStatus } as const) : undefined;
  if (job) {
    return mergeJobUpdate(job, patch, queueOpts);
  }
  if (prior && !useJobStore.getState().isJobBlacklisted(bookingId)) {
    return mergeJobUpdate(prior, patch, queueOpts);
  }
  return job;
}

/** Apply dispatchConsole refresh hint immediately — avoids Assign-tab flash while Firebase catches up. */
function optimisticDispatchRefresh(
  companyId: string,
  bookingId: number,
  refresh: DispatchRefreshPayload,
  pendingRef: Map<number, Job>,
  bookingsRef: Map<number, Job>,
  upsertJob: (job: Job) => void,
  replaceJob: (job: Job) => void,
  removeJob: (id: number) => void,
  clearRemovedJob: (id: number) => void,
  syncAll: () => void,
): void {
  if (refreshImpliesTerminal(refresh)) {
    handleTerminalRefresh(
      bookingId,
      pendingRef,
      bookingsRef,
      removeJob,
      syncAll,
      refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
      terminalRefreshDebug(refresh, 'optimisticDispatchRefresh:refreshImpliesTerminal'),
    );
    return;
  }
  if (!refresh.status) return;
  if (useJobStore.getState().isJobBlacklisted(bookingId)) return;

  const prior = existingJobSnapshot(bookingId, pendingRef, bookingsRef);
  const targetStatus = refresh.status ? normalizeJobStatus(refresh.status) : null;

  // Terminal status on the wire — remove, never merge into Assign/U-A.
  if (targetStatus && TERMINAL_BOOKING_STATUSES.has(targetStatus)) {
    handleTerminalRefresh(
      bookingId,
      pendingRef,
      bookingsRef,
      removeJob,
      syncAll,
      refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
      terminalRefreshDebug(refresh, 'optimisticDispatchRefresh:terminalStatus'),
    );
    return;
  }

  if (
    prior &&
    normalizeJobStatus(prior.status) === 'Queued' &&
    (POOL_RESTORE_ACTIONS.has(refresh.action || '') ||
      targetStatus === 'Pending' ||
      targetStatus === 'No One')
  ) {
    clearQueueAwaitingAllbookings(bookingId);
  }
  if (
    targetStatus === 'Pending' ||
    targetStatus === 'No One' ||
    targetStatus === 'Scheduled' ||
    POOL_RESTORE_ACTIONS.has(refresh.action || '') ||
    refresh.action === 'cancel' ||
    refresh.action === 'no-show'
  ) {
    clearOfferAwaitingAllbookings(bookingId);
    clearOptimisticLiveTransition(bookingId);
  }

  let job: Job | null = null;
  if (prior) {
    job = applyRefreshStatusHint(null, prior, refresh, bookingId);
  } else if (refresh.action === 'queue' || targetStatus === 'Queued') {
    job = minimalJobFromDispatchRefresh(bookingId, companyId, refresh);
  }
  if (!job) return;

  pendingRef.delete(bookingId);
  let st = normalizeJobStatus(job.status);

  // Authoritative Queued + real driver — REPLACE store entry (no merge with stale Pending).
  if (
    (refresh.action === 'queue' || st === 'Queued' || targetStatus === 'Queued') &&
    isGenuineQueuedJob(job)
  ) {
    markQueueAwaitingAllbookings(bookingId);
    pendingRef.delete(bookingId);
    job = applyQueueAuthoritativeReplace(prior, job, refresh.driverId);
    st = 'Queued';
    bookingsRef.set(bookingId, job);
    if (['accept', 'assign', 'offer', 'queue', 'active'].includes(refresh.action || '')) {
      markOptimisticLiveTransition(bookingId);
      if (refresh.updateSeq != null && refresh.updateSeq > 0) {
        clearCompletedJobSuppress(bookingId);
      }
    }
    replaceJob(job);
    syncAll();
    return;
  }

  if (ACTIVE_BOOKING_STATUSES.has(st)) {
    bookingsRef.set(job.id, job);
  } else if (st === 'Pending' || st === 'No One') {
    pendingRef.set(job.id, job);
    bookingsRef.delete(bookingId);
  }
  if (refresh.action === 'offer' && st === 'Offered') {
    markOfferAwaitingAllbookings(bookingId);
  }
  if (['accept', 'assign', 'offer', 'queue', 'active'].includes(refresh.action || '')) {
    markOptimisticLiveTransition(bookingId);
    if (refresh.updateSeq != null && refresh.updateSeq > 0) {
      clearCompletedJobSuppress(bookingId);
    }
  }
  upsertJob(job);
  syncAll();
}

/** Server wrote dispatchConsole/{cid}/refresh — re-read Firebase for one job (or full sync). */
async function refreshJobFromFirebaseCaches(
  companyId: string,
  bookingId: number,
  refresh: DispatchRefreshPayload,
  pendingRef: Map<number, Job>,
  bookingsRef: Map<number, Job>,
  hooks: {
    applyPending: (key: string, rec: Record<string, unknown>, notify: boolean) => void;
    removeJob: (id: number) => void;
    clearRemovedJob: (id: number) => void;
    replaceJob: (job: Job) => void;
    syncAll: () => void;
  },
) {
  const action = refresh.action;
  const prior = existingJobSnapshot(bookingId, pendingRef, bookingsRef);

  if (refreshImpliesTerminal(refresh)) {
    handleTerminalRefresh(
      bookingId,
      pendingRef,
      bookingsRef,
      hooks.removeJob,
      hooks.syncAll,
      refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
      terminalRefreshDebug(refresh, 'refreshJobFromFirebaseCaches:refreshImpliesTerminal'),
    );
    return;
  }

  const db = getDb();
  const [abSnap, pjSnap] = await Promise.all([
    get(ref(db, `allbookings/${companyId}/${bookingId}`)),
    get(ref(db, `pendingjobs/${companyId}/${bookingId}`)),
  ]);

  pendingRef.delete(bookingId);

  let job: Job | null = null;
  const abVal = abSnap.val();
  const pjVal = pjSnap.val();
  const pjRecord = pjVal && typeof pjVal === 'object' ? (pjVal as Record<string, unknown>) : null;
  const fbSeq = seqFromFirebaseRecord(abVal as Record<string, unknown>) ?? seqFromFirebaseRecord(pjRecord);
  const trustPoolRestore = refreshTrustsPoolRestore(refresh, fbSeq);
  if (abVal && typeof abVal === 'object') {
    const rec = abVal as Record<string, unknown>;
    const parsed = jobFromFirebase(String(bookingId), rec, companyId);
    if (parsed && !useJobStore.getState().isJobBlacklisted(parsed.id)) {
      let st = jobStatusFromFirebaseRecord(rec);
      if (action === 'queue' && isQueueAwaitingAllbookings(bookingId) && st !== 'Queued') {
        st = 'Queued';
      }
      // Firebase terminal → REMOVE from store entirely (never merge into Assign).
      if (TERMINAL_BOOKING_STATUSES.has(st)) {
        handleTerminalRefresh(
          bookingId,
          pendingRef,
          bookingsRef,
          hooks.removeJob,
          hooks.syncAll,
          refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
          { action, status: st, caller: 'refreshJobFromFirebaseCaches:allbookingsTerminal' },
        );
        return;
      }
      if (ACTIVE_BOOKING_STATUSES.has(st)) {
        if (trustPoolRestore) {
          job = applyRefreshStatusHint(null, prior, refresh, bookingId);
        } else if (!isCompletedJobSuppressed(bookingId)) {
          job = parsed;
        }
      } else if (action !== 'accept' && action !== 'assign' && action !== 'offer' && action !== 'queue' && action !== 'active') {
        bookingsRef.delete(bookingId);
      }
    }
  } else if (action === 'cancel' || action === 'no-show') {
    handleTerminalRefresh(
      bookingId,
      pendingRef,
      bookingsRef,
      hooks.removeJob,
      hooks.syncAll,
      refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
      { action, status: refresh.status, caller: 'refreshJobFromFirebaseCaches:noAllbookingsTerminalAction' },
    );
    return;
  }

  if (!job && prior && ['accept', 'assign', 'offer', 'active', 'queue'].includes(action || '')) {
    job = applyRefreshStatusHint(null, prior, refresh, bookingId);
  }

  if (action === 'queue') {
    markQueueAwaitingAllbookings(bookingId);
  }
  if (action === 'offer') {
    markOfferAwaitingAllbookings(bookingId);
  }
  if (
    POOL_RESTORE_ACTIONS.has(action || '') &&
    prior &&
    normalizeJobStatus(prior.status) === 'Queued'
  ) {
    clearQueueAwaitingAllbookings(bookingId);
  }

  // Apply refresh hint — terminal returns null (already handled above for FB terminal).
  const hinted = applyRefreshStatusHint(job, prior, refresh, bookingId);
  if (
    refresh.status &&
    TERMINAL_BOOKING_STATUSES.has(normalizeJobStatus(refresh.status))
  ) {
    handleTerminalRefresh(
      bookingId,
      pendingRef,
      bookingsRef,
      hooks.removeJob,
      hooks.syncAll,
      refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
      { action, status: refresh.status, caller: 'refreshJobFromFirebaseCaches:refreshStatusTerminal' },
    );
    return;
  }
  job = hinted;

  // Firebase / refresh says Queued with a real driver — REPLACE, do not merge Pending.
  const fbStatus =
    abVal && typeof abVal === 'object'
      ? jobStatusFromFirebaseRecord(abVal as Record<string, unknown>)
      : job
        ? normalizeJobStatus(job.status)
        : null;
  const queuedCandidate =
    job &&
    (action === 'queue' ||
      fbStatus === 'Queued' ||
      (refresh.status && normalizeJobStatus(refresh.status) === 'Queued'))
      ? applyQueueAuthoritativeReplace(prior, job, refresh.driverId)
      : null;
  if (queuedCandidate && isGenuineQueuedJob(queuedCandidate)) {
    markQueueAwaitingAllbookings(bookingId);
    pendingRef.delete(bookingId);
    if (fbSeq != null) {
      queuedCandidate.updateSeq = Math.max(queuedCandidate.updateSeq ?? 0, fbSeq);
    }
    const fbBooking =
      abVal && typeof abVal === 'object'
        ? normalizeJobStatus(String((abVal as Record<string, unknown>).BookingStatus ?? ''))
        : '';
    if (fbBooking === 'Queued') clearQueueAwaitingAllbookings(bookingId);
    bookingsRef.set(queuedCandidate.id, queuedCandidate);
    hooks.replaceJob(queuedCandidate);
    // Never apply stale pendingjobs Pending over confirmed Queued.
    if (
      pjRecord &&
      pendingSnapshotWouldRegressQueue(bookingId, pjRecord, {
        bookingsRef,
        abRec: abVal && typeof abVal === 'object' ? (abVal as Record<string, unknown>) : null,
      })
    ) {
      pendingRef.delete(bookingId);
    }
    hooks.syncAll();
    return;
  }

  if (job && fbSeq != null && (job.updateSeq ?? 0) < fbSeq && !trustPoolRestore) {
    job = mergeJobUpdate(job, { updateSeq: fbSeq } as Job);
  }

  if (job && !useJobStore.getState().isJobBlacklisted(job.id)) {
    const st = jobStatusFromFirebaseRecord(
      abVal && typeof abVal === 'object'
        ? (abVal as Record<string, unknown>)
        : { BookingStatus: job.status, Status: job.status },
    );
    if (TERMINAL_BOOKING_STATUSES.has(st)) {
      handleTerminalRefresh(
        bookingId,
        pendingRef,
        bookingsRef,
        hooks.removeJob,
        hooks.syncAll,
        refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
        { action, status: st, caller: 'refreshJobFromFirebaseCaches:jobBlockTerminal' },
      );
      return;
    }
    if (st !== job.status && !trustPoolRestore) {
      job = mergeJobUpdate(job, { status: st } as Job);
    }
    if (st === 'Offered') {
      clearOfferAwaitingAllbookings(bookingId);
    }
    if (st === 'Pending' || st === 'No One' || st === 'Scheduled' || trustPoolRestore) {
      clearOfferAwaitingAllbookings(bookingId);
    }
    if (ACTIVE_BOOKING_STATUSES.has(st)) {
      if (!isCompletedJobSuppressed(job.id)) {
        bookingsRef.set(job.id, job);
      }
    } else if (st === 'Pending' || st === 'No One') {
      pendingRef.set(job.id, job);
      bookingsRef.delete(bookingId);
    }
  }

  if (pjRecord) {
    if (pendingSnapshotWouldRegressPool(refresh, pjRecord)) {
      if (import.meta.env.DEV) {
        console.warn(
          `[dispatch-refresh] ignored stale pendingjobs #${bookingId}`,
          pjRecord.BookingStatus ?? pjRecord.Status,
          '→ refresh',
          refresh.status,
        );
      }
      if (job) pendingRef.set(job.id, job);
    } else if (
      pendingSnapshotWouldRegressQueue(bookingId, pjRecord, {
        bookingsRef,
        abRec: abVal && typeof abVal === 'object' ? (abVal as Record<string, unknown>) : null,
      })
    ) {
      if (import.meta.env.DEV) {
        console.warn(
          `[dispatch-refresh] ignored stale pendingjobs #${bookingId}`,
          pjRecord.BookingStatus ?? pjRecord.Status,
          '→ confirmed Queued',
        );
      }
      pendingRef.delete(bookingId);
      if (job) {
        const queued = applyQueueAuthoritativeReplace(prior, job, refresh.driverId);
        bookingsRef.set(queued.id, queued);
        hooks.replaceJob(queued);
      }
    } else {
      hooks.applyPending(String(bookingId), pjRecord, false);
    }
  } else {
    if (!pendingjobsAbsentIsPoolRestore(job, refresh)) {
      pendingRef.delete(bookingId);
    } else if (job) {
      pendingRef.set(job.id, job);
    }
    const liveActions = new Set(['accept', 'assign', 'offer', 'queue', 'active', 'status', 'timeout', 'decline', 'recall', 'scheduled_release']);
    if (action === 'cancel' || action === 'no-show') {
      handleTerminalRefresh(
        bookingId,
        pendingRef,
        bookingsRef,
        hooks.removeJob,
        hooks.syncAll,
        refresh.updateSeq ?? priorTerminalSuppressSeq(bookingId, pendingRef, bookingsRef),
        { action, status: refresh.status, caller: 'refreshJobFromFirebaseCaches:noPendingjobsTerminalAction' },
      );
      return;
    } else if (!liveActions.has(action || '') && !job) {
      hooks.removeJob(bookingId);
      hooks.clearRemovedJob(bookingId);
    }
  }

  hooks.syncAll();
}

export function useJobs(companyId: string | null) {
  const setJobs = useJobStore((s) => s.setJobs);
  const upsertJob = useJobStore((s) => s.upsertJob);
  const replaceJob = useJobStore((s) => s.replaceJob);
  const removeJob = useJobStore((s) => s.removeJob);
  const clearRemovedJob = useJobStore((s) => s.clearRemovedJob);
  const pendingRef = useRef<Map<number, Job>>(new Map());
  const bookingsRef = useRef<Map<number, Job>>(new Map());
  const lastDispatchRefreshAtRef = useRef('');

  useEffect(() => {
    if (!companyId) return;
    let cancelled = false;
    const unsubs: Array<() => void> = [];
    let bootstrapping = true;

    listenerPendingCache = pendingRef.current;
    listenerBookingsCache = bookingsRef.current;

    void (async () => {
      const authCtx = await bootstrapDispatchFirebaseAccess(companyId);
      if (cancelled) return;

      const db = getDb();

    const syncAll = () => {
      purgeStalePendingForQueuedBookings(
        pendingRef.current,
        bookingsRef.current,
        useJobStore.getState().jobs,
      );
      reinjectQueueAwaitingJobs(
        bookingsRef.current,
        useJobStore.getState().jobs,
        pendingRef.current,
      );
      reinjectOfferAwaitingJobs(
        bookingsRef.current,
        pendingRef.current,
        useJobStore.getState().jobs,
      );
      for (const j of mergeJobs([pendingRef.current, bookingsRef.current])) {
        if (
          ACTIVE_BOOKING_STATUSES.has(normalizeJobStatus(j.status)) &&
          !useJobStore.getState().isJobBlacklisted(j.id)
        ) {
          clearRemovedJob(j.id);
        }
      }
      const removed = new Set(useJobStore.getState().removedJobIds);
      const mergedPreFilter = mergeJobs([pendingRef.current, bookingsRef.current]);
      const merged = mergedPreFilter.filter((j) => !removed.has(j.id));
      const byId = new Map(merged.map((j) => [j.id, j]));
      const storeJobs = useJobStore.getState().jobs;
      for (const [id, job] of byId) {
        const existing = storeJobs.find((j) => j.id === id);
        if (isQueueAwaitingAllbookings(id)) {
          const base = existing ?? job;
          const baseSt = normalizeJobStatus(base.status);
          if (TERMINAL_BOOKING_STATUSES.has(baseSt) || isCompletedJobSuppressed(id)) {
            clearQueueAwaitingAllbookings(id);
            continue;
          }
          byId.set(
            id,
            mergeJobUpdate(base, { ...job, status: 'Queued' }, { forceStatus: 'Queued' }),
          );
          continue;
        }
        if (existing) {
          byId.set(id, mergeJobUpdate(existing, job, queueAwaitingMergeOpts(id)));
        }
      }
      for (const j of storeJobs) {
        if (byId.has(j.id) || removed.has(j.id)) continue;
        if (shouldPreserveAbsentStoreJob(j, pendingRef.current, bookingsRef.current)) {
          const awaiting = isQueueAwaitingAllbookings(j.id);
          const terminal = TERMINAL_BOOKING_STATUSES.has(normalizeJobStatus(j.status));
          if (awaiting && terminal) clearQueueAwaitingAllbookings(j.id);
          byId.set(
            j.id,
            awaiting && !terminal
              ? mergeJobUpdate(j, { status: 'Queued' }, { forceStatus: 'Queued' })
              : j,
          );
        }
      }
      logSyncAllMergePipeline({
        pendingRef: pendingRef.current,
        bookingsRef: bookingsRef.current,
        storeJobs,
        mergedPreFilter,
        mergedPostFilter: merged,
        byId,
        removed,
      });
      setJobs(Array.from(byId.values()));
    };

    const notifyNewJob = (job: Job) => {
      if (!isUaJob(job) || !isExternalJobSource(job.source)) return;
      notifyNewBooking(job.id);
    };

    const applyPending = (key: string, rec: Record<string, unknown>, notify: boolean) => {
      const jobId = parseInt(String(rec.BookingId ?? rec.bookingId ?? key), 10);
      if (!jobId || isBlacklisted(jobId)) return;

      const job = jobFromFirebase(key, rec, companyId);
      if (!job || isBlacklisted(job.id)) return;

      const pendingEffective = jobStatusFromFirebaseRecord(rec);
      if (
        isCompletedJobSuppressed(jobId) &&
        !TERMINAL_BOOKING_STATUSES.has(pendingEffective) &&
        (ACTIVE_BOOKING_STATUSES.has(pendingEffective) ||
          pendingEffective === 'Assigned' ||
          pendingEffective === 'Picking' ||
          pendingEffective === 'Arrived' ||
          pendingEffective === 'Offered')
      ) {
        pendingRef.current.delete(jobId);
        return;
      }

      const bookingsQueued = bookingsRef.current.get(jobId);
      const storeQueued = useJobStore.getState().jobs.find((j) => j.id === jobId);
      if (
        normalizeJobStatus(job.status) !== 'Queued' &&
        (normalizeJobStatus(bookingsQueued?.status) === 'Queued' ||
          normalizeJobStatus(storeQueued?.status) === 'Queued')
      ) {
        pendingRef.current.delete(jobId);
        return;
      }

      if (
        !isQueueAwaitingAllbookings(jobId) &&
        !isDispatchPoolRowLive(jobId, rec, pendingRef.current)
      ) {
        pendingRef.current.delete(jobId);
        return;
      }

      if (isQueueAwaitingAllbookings(jobId)) {
        pendingRef.current.delete(jobId);
        const forced = mergeJobUpdate(job, { status: 'Queued' }, { forceStatus: 'Queued' });
        bookingsRef.current.set(jobId, forced);
        const storeJob = useJobStore.getState().jobs.find((j) => j.id === jobId);
        const merged = storeJob
          ? mergeJobUpdate(storeJob, forced, { forceStatus: 'Queued' })
          : forced;
        upsertJob(merged);
        syncAll();
        return;
      }

      const effectiveStatus = jobStatusFromFirebaseRecord(rec);
      if (TERMINAL_BOOKING_STATUSES.has(effectiveStatus)) {
        const storeJobs = useJobStore.getState().jobs;
        if (
          staleTerminalAllbookingsSuperseded(
            job.id,
            rec,
            pendingRef.current,
            bookingsRef.current,
            storeJobs,
          )
        ) {
          return;
        }
        pendingRef.current.delete(job.id);
        bookingsRef.current.delete(job.id);
        markCompletedJobSuppress(job.id);
        removeJob(job.id);
        clearRemovedJob(job.id);
        syncAll();
        return;
      }

      const booking = bookingsRef.current.get(job.id);
      const storeJob = useJobStore.getState().jobs.find((j) => j.id === job.id);
      const pendingSt = normalizeJobStatus(effectiveStatus);
      const liveQueued =
        isQueueAwaitingAllbookings(jobId) ||
        normalizeJobStatus(booking?.status) === 'Queued' ||
        normalizeJobStatus(storeJob?.status) === 'Queued';
      // Queued jobs must never be demoted by a stale pendingjobs partial (edit fanout writes pool shape).
      if (liveQueued && pendingSt !== 'Queued') {
        pendingRef.current.delete(jobId);
        return;
      }

      const liveAssigned =
        normalizeJobStatus(booking?.status) === 'Assigned' ||
        normalizeJobStatus(storeJob?.status) === 'Assigned';
      // Assigned jobs must never be demoted by a stale pendingjobs partial (edit fanout writes pool shape).
      if (liveAssigned && pendingSt !== 'Assigned') {
        pendingRef.current.delete(jobId);
        return;
      }

      if (pendingSt === 'Pending' || pendingSt === 'No One' || pendingSt === 'Scheduled') {
        clearOfferAwaitingAllbookings(jobId);
        bookingsRef.current.delete(jobId);
      }

      pendingRef.current.set(job.id, job);
      let merged = booking ? mergeJobUpdate(booking, job) : job;
      if (storeJob) merged = mergeJobUpdate(storeJob, merged);
      upsertJob(merged);
      syncAll();
      if (notify) notifyNewJob(job);
    };

    const jobsRef = ref(db, `pendingjobs/${companyId}`);
    const bRef = ref(db, `allbookings/${companyId}`);

    const addJobToStore = (snap: { key: string | null; val: () => unknown }) => {
      const jobId = parseInt(snap.key || '0', 10);
      if (!jobId || isBlacklisted(jobId)) return;
      const val = snap.val();
      if (!val || typeof val !== 'object') return;
      applyPending(snap.key!, val as Record<string, unknown>, !bootstrapping);
    };

    const updateJobInStore = (snap: { key: string | null; val: () => unknown }) => {
      const jobId = parseInt(snap.key || '0', 10);
      if (!jobId || isBlacklisted(jobId)) return;
      const val = snap.val();
      if (!val || typeof val !== 'object') return;
      applyPending(snap.key!, val as Record<string, unknown>, false);
    };

    const removeJobFromStore = (snap: { key: string | null }) => {
      const jobId = parseInt(snap.key || '0', 10);
      if (!jobId) return;
      pendingRef.current.delete(jobId);
      // pendingjobs DELETE is normal after accept/queue — do not purge live jobs here.
      // refreshJobFromFirebaseCaches + allbookings own removal; deleting here caused Assign-tab flash.
      syncAll();
    };

    unsubs.push(onChildAdded(jobsRef, addJobToStore));

    // Existing children fire synchronously during onChildAdded registration
    bootstrapping = false;

    unsubs.push(onChildChanged(jobsRef, updateJobInStore));
    unsubs.push(onChildRemoved(jobsRef, removeJobFromStore));

    unsubs.push(
      onValue(bRef, (snap) => {
        bookingsRef.current = new Map();
        const terminalRows: Array<{ id: number; seq: number }> = [];
        const seenInSnapshot = new Set<number>();
        const val = snap.val();
        if (val && typeof val === 'object') {
          for (const [key, rec] of Object.entries(val as Record<string, Record<string, unknown>>)) {
            const jobId = parseInt(String(rec.BookingId ?? rec.bookingId ?? key), 10);
            if (!jobId) continue;
            seenInSnapshot.add(jobId);

            const job = jobFromFirebase(key, rec, companyId);
            if (!job) {
              traceAllbookingsIngest(jobId, 'parse failed', { firebaseKey: key });
              continue;
            }

            if (!isDispatchPoolRowLive(jobId, rec, pendingRef.current)) {
              traceAllbookingsIngest(jobId, 'skipped orphan (stale pool row)', {
                recordActivityMs: recordActivityMs(rec),
                hasPending: pendingRef.current.has(jobId),
                bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                statusRaw: rec.Status ?? rec.status ?? null,
              });
              continue;
            }

            // Prefer record-level resolution (BookingStatus wins over stale Status: Pending).
            let effectiveStatus = coerceAllbookingsLiveStatus(
              rec,
              normalizeJobStatus(jobStatusFromFirebaseRecord(rec)),
            );
            const fbAttached = new Set(['Assigned', 'Picking', 'Arrived', 'Active', 'OnTrip', 'Offered', 'Queued']);
            const abRaw = normalizeJobStatus(
              String(rec.BookingStatus ?? rec.bookingStatus ?? rec.Status ?? rec.status ?? ''),
            );
            if (fbAttached.has(abRaw) && !fbAttached.has(effectiveStatus)) {
              effectiveStatus = abRaw;
            }
            if (shouldSkipStaleLiveAllbookingsIngest(jobId, effectiveStatus, rec)) {
              continue;
            }
            if (ACTIVE_BOOKING_STATUSES.has(effectiveStatus)) {
              clearRemovedJob(jobId);
            } else if (isBlacklisted(jobId)) {
              traceAllbookingsIngest(jobId, 'skipped blacklisted', {
                effectiveStatus,
                bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                statusRaw: rec.Status ?? rec.status ?? null,
              });
              continue;
            }
            if (
              isQueueAwaitingAllbookings(jobId) &&
              !TERMINAL_BOOKING_STATUSES.has(effectiveStatus) &&
              effectiveStatus !== 'Queued'
            ) {
              if (
                effectiveStatus === 'No One' ||
                effectiveStatus === 'Pending' ||
                effectiveStatus === 'Scheduled'
              ) {
                clearQueueAwaitingAllbookings(jobId);
              } else {
                pendingRef.current.delete(jobId);
                effectiveStatus = 'Queued';
              }
            }
            let stored =
              effectiveStatus !== job.status ? { ...job, status: effectiveStatus } : job;

            if (isCompletedJobSuppressed(jobId) && !TERMINAL_BOOKING_STATUSES.has(effectiveStatus)) {
              if (ACTIVE_BOOKING_STATUSES.has(effectiveStatus)) {
                if (!shouldClearCompletedSuppress(jobId, rec)) {
                  traceAllbookingsIngest(jobId, 'skipped completedSuppressed (stale Active)', {
                    effectiveStatus,
                    bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                    statusRaw: rec.Status ?? rec.status ?? null,
                  });
                  continue;
                }
                clearCompletedJobSuppress(jobId);
              } else {
                traceAllbookingsIngest(jobId, 'skipped completedSuppressed', {
                  effectiveStatus,
                  bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                  statusRaw: rec.Status ?? rec.status ?? null,
                });
                continue;
              }
            }

            if (TERMINAL_BOOKING_STATUSES.has(effectiveStatus)) {
              const storeJobs = useJobStore.getState().jobs;
              const superseding = pickLiveJobSupersedingStaleTerminal(
                jobId,
                rec,
                pendingRef.current,
                bookingsRef.current,
                storeJobs,
              );
              if (superseding) {
                effectiveStatus = normalizeJobStatus(superseding.status);
                stored = mergeJobUpdate(
                  superseding,
                  { ...job, status: effectiveStatus },
                  effectiveStatus === 'Queued'
                    ? { forceStatus: 'Queued' }
                    : queueAwaitingMergeOpts(jobId),
                );
                clearCompletedJobSuppress(jobId);
                traceAllbookingsIngest(jobId, 'stale terminal superseded by live row', {
                  effectiveStatus,
                  supersedingStatus: superseding.status,
                  supersedingUpdateSeq: superseding.updateSeq ?? null,
                  bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                  statusRaw: rec.Status ?? rec.status ?? null,
                });
              } else if (
                staleTerminalAllbookingsSuperseded(
                  stored.id,
                  rec,
                  pendingRef.current,
                  bookingsRef.current,
                  storeJobs,
                )
              ) {
                traceAllbookingsIngest(jobId, 'skipped staleTerminalSuperseded (no live row)', {
                  effectiveStatus,
                  bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                  statusRaw: rec.Status ?? rec.status ?? null,
                });
                continue;
              } else {
                terminalRows.push({
                  id: stored.id,
                  seq: stored.updateSeq ?? seqFromFirebaseRecord(rec) ?? 0,
                });
                traceAllbookingsIngest(jobId, 'terminal', {
                  effectiveStatus,
                  bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                  statusRaw: rec.Status ?? rec.status ?? null,
                });
                continue;
              }
            }

            if (ACTIVE_BOOKING_STATUSES.has(effectiveStatus)) {
              if (effectiveStatus === 'Queued') {
                pendingRef.current.delete(jobId);
              }
              bookingsRef.current.set(stored.id, stored);
              traceAllbookingsIngest(jobId, 'ingest', {
                effectiveStatus,
                storedStatus: stored.status,
                bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                statusRaw: rec.Status ?? rec.status ?? null,
                blacklisted: isBlacklisted(jobId),
                completedSuppressed: isCompletedJobSuppressed(jobId),
              });
              if (effectiveStatus === 'Queued') {
                const fbBooking = normalizeJobStatus(String(rec.BookingStatus ?? ''));
                if (fbBooking === 'Queued' || allbookingsRecordIsQueued(rec)) {
                  clearQueueAwaitingAllbookings(stored.id);
                }
              }
              if (effectiveStatus === 'Offered') {
                clearOfferAwaitingAllbookings(stored.id);
              }
            } else if (isPoolUaStatus(effectiveStatus)) {
              pendingRef.current.set(stored.id, stored);
            } else {
              traceAllbookingsIngest(jobId, 'skipped (not active/ua)', {
                effectiveStatus,
                storedStatus: stored.status,
                bookingStatusRaw: rec.BookingStatus ?? rec.bookingStatus ?? null,
                statusRaw: rec.Status ?? rec.status ?? null,
                blacklisted: isBlacklisted(jobId),
                completedSuppressed: isCompletedJobSuppressed(jobId),
                terminal: TERMINAL_BOOKING_STATUSES.has(effectiveStatus),
              });
            }
          }
        }
        logAllbookingsSnapshotSummary(companyId, authCtx, val, seenInSnapshot);
        for (const traceId of DISPATCH_QUEUE_TRACE_IDS) {
          if (!seenInSnapshot.has(traceId)) {
            console.log('[dispatch-queue-debug] allbookings missing from snapshot', {
              jobId: traceId,
              snapshotChildCount:
                val && typeof val === 'object'
                  ? Object.keys(val as Record<string, unknown>).length
                  : 0,
            });
            void get(ref(db, `allbookings/${companyId}/${traceId}`))
              .then((directSnap) => {
                const directVal = directSnap.val() as Record<string, unknown> | null;
                console.log('[dispatch-queue-debug] allbookings direct-get probe', {
                  jobId: traceId,
                  exists: directSnap.exists(),
                  bookingStatusRaw: directVal?.BookingStatus ?? directVal?.bookingStatus ?? null,
                  statusRaw: directVal?.Status ?? directVal?.status ?? null,
                  driverId: directVal?.DriverId ?? directVal?.driverId ?? null,
                });
              })
              .catch((err) => {
                console.log('[dispatch-queue-debug] allbookings direct-get probe failed', {
                  jobId: traceId,
                  error: err instanceof Error ? err.message : String(err),
                });
              });
            void get(ref(db, `pendingjobs/${companyId}/${traceId}`))
              .then((pjSnap) => {
                const pjVal = pjSnap.val() as Record<string, unknown> | null;
                console.log('[dispatch-queue-debug] pendingjobs direct-get probe', {
                  jobId: traceId,
                  exists: pjSnap.exists(),
                  bookingStatusRaw: pjVal?.BookingStatus ?? pjVal?.bookingStatus ?? null,
                  statusRaw: pjVal?.Status ?? pjVal?.status ?? null,
                });
              })
              .catch(() => undefined);
          }
        }
        for (const row of terminalRows) {
          recordTerminalRefreshGuard(row.id, {
            updateSeq: row.seq,
            source: 'allbookings:terminal',
          });
          clearQueueAwaitingAllbookings(row.id);
          clearOfferAwaitingAllbookings(row.id);
          pendingRef.current.delete(row.id);
          bookingsRef.current.delete(row.id);
          markCompletedJobSuppress(row.id, row.seq);
          removeJob(row.id);
          clearRemovedJob(row.id);
        }
        reinjectQueueAwaitingJobs(
          bookingsRef.current,
          useJobStore.getState().jobs,
          pendingRef.current,
        );
        reinjectOfferAwaitingJobs(
          bookingsRef.current,
          pendingRef.current,
          useJobStore.getState().jobs,
        );
        syncAll();
      })
    );

    unsubs.push(
      onValue(ref(db, `dispatchConsole/${companyId}/refresh`), (snap) => {
        const v = snap.val() as {
          at?: number;
          terminalAt?: number;
          bookingId?: number;
          action?: string;
          status?: string;
          driverId?: string | number;
          declinedDriverId?: string;
          returnReason?: string;
          updateSeq?: number;
        } | null;
        const bid = parseInt(String(v?.bookingId ?? '0'), 10);
        const signalAt =
          typeof v?.at === 'number' ? v.at : parseInt(String(v?.at ?? '0'), 10) || 0;
        const terminalAt =
          typeof v?.terminalAt === 'number'
            ? v.terminalAt
            : parseInt(String(v?.terminalAt ?? '0'), 10) || 0;
        const refreshKey = `${signalAt}:${terminalAt}:${bid}`;
        console.log('[dispatch-terminal] dispatchConsole/refresh received', {
          bookingId: bid,
          action: v?.action ?? null,
          status: v?.status ?? null,
          driverId: v?.driverId ?? null,
          updateSeq: v?.updateSeq ?? null,
          at: signalAt || null,
          terminalAt: terminalAt || null,
          lastTerminalAt: bid ? lastTerminalAtByBookingId.get(bid)?.terminalAt ?? null : null,
          refreshKey,
          deduped: refreshKey === lastDispatchRefreshAtRef.current,
        });
        if (refreshKey === lastDispatchRefreshAtRef.current) return;
        lastDispatchRefreshAtRef.current = refreshKey;
        if (!bid) {
          syncAll();
          return;
        }
        const refreshPayload: DispatchRefreshPayload = {
          action: v?.action,
          status: v?.status,
          driverId: v?.driverId != null ? String(v.driverId) : undefined,
          declinedDriverId: v?.declinedDriverId,
          returnReason: v?.returnReason,
          updateSeq:
            v?.updateSeq != null
              ? parseInt(String(v.updateSeq), 10)
              : undefined,
          at: signalAt || undefined,
          terminalAt: terminalAt || undefined,
        };
        if (refreshImpliesTerminal(refreshPayload)) {
          recordTerminalRefreshGuard(bid, {
            at: signalAt,
            terminalAt,
            updateSeq: refreshPayload.updateSeq,
            source: 'dispatchConsole/refresh:terminal',
          });
        } else if (shouldIgnoreStaleLiveDispatchRefresh(bid, refreshPayload, signalAt)) {
          return;
        } else if (
          refreshPayload.status &&
          STALE_GUARD_LIVE_STATUSES.has(normalizeJobStatus(refreshPayload.status)) &&
          !lastTerminalAtByBookingId.has(bid)
        ) {
          console.log('[dispatch-terminal] live refresh with no terminal guard recorded', {
            bookingId: bid,
            action: refreshPayload.action ?? null,
            status: refreshPayload.status ?? null,
            signalAt: signalAt || null,
            refreshUpdateSeq: refreshPayload.updateSeq ?? null,
          });
        }
        notifyOfferReturned(bid, refreshPayload);
        notifyFromDispatchRefresh({
          bookingId: bid,
          action: refreshPayload.action,
          status: refreshPayload.status,
          driverId: refreshPayload.driverId,
          signalAt: signalAt || undefined,
          job: existingJobSnapshot(bid, pendingRef.current, bookingsRef.current),
        });
        optimisticDispatchRefresh(
          companyId,
          bid,
          refreshPayload,
          pendingRef.current,
          bookingsRef.current,
          upsertJob,
          replaceJob,
          removeJob,
          clearRemovedJob,
          syncAll,
        );
        void refreshJobFromFirebaseCaches(
          companyId,
          bid,
          refreshPayload,
          pendingRef.current,
          bookingsRef.current,
          {
            applyPending,
            removeJob,
            clearRemovedJob,
            replaceJob,
            syncAll,
          },
        );
      })
    );
    })();

    return () => {
      cancelled = true;
      for (const u of unsubs) u();
      if (listenerPendingCache === pendingRef.current) listenerPendingCache = null;
      if (listenerBookingsCache === bookingsRef.current) listenerBookingsCache = null;
    };
  }, [companyId, setJobs, upsertJob, removeJob, clearRemovedJob]);

  return useJobStore((s) => s.jobs);
}

const dispatchNowNotifiedRef = { current: new Set<number>() };

/** Fire toast + alert sound when a pre-booked job enters its dispatch window. */
export function useDispatchWindowAlerts(jobs: Job[]) {
  useEffect(() => {
    const now = new Date();
    for (const job of jobs) {
      if (jobTabForStatus(job) !== 'ua' || !isPreBookedJob(job, now)) continue;
      const dispatchAt = jobDispatchTime(job);
      if (!dispatchAt || now.getTime() < dispatchAt.getTime()) continue;
      if (dispatchNowNotifiedRef.current.has(job.id)) continue;
      dispatchNowNotifiedRef.current.add(job.id);
      useUiStore.getState().addToast({
        type: 'warning',
        title: 'DISPATCH NOW',
        message: `#${job.id} ${job.pickAddress || 'Ready to assign'}`,
        category: 'general',
      });
    }
  }, [jobs]);
}

export function useClosedJobs(companyId: string | null, enabled: boolean) {
  const [closed, setClosed] = useState<Job[]>([]);

  useEffect(() => {
    if (!companyId || !enabled) return;
    const db = getDb();

    let allbookingsById = new Map<number, { job: Job; rec: Record<string, unknown> }>();
    let completedById = new Map<number, Record<string, unknown>>();

    const mergeAndSet = () => {
      const merged = new Map<number, Job>();

      for (const [id, { job, rec }] of allbookingsById) {
        const overlay = completedById.get(id);
        merged.set(id, mergeClosedJobRecords(job, overlay, companyId));
      }

      for (const [id, rec] of completedById) {
        if (merged.has(id)) continue;
        const job = jobFromClosedFirebaseRecord(String(id), rec, companyId);
        if (job) merged.set(id, job);
      }

      setClosed(
        Array.from(merged.values()).sort((a, b) => (b.completedAt || 0) - (a.completedAt || 0)),
      );
    };

    const unsubs = [
      onValue(ref(db, `allbookings/${companyId}`), (snap) => {
        const next = new Map<number, { job: Job; rec: Record<string, unknown> }>();
        const val = snap.val();
        if (val && typeof val === 'object') {
          for (const [key, rec] of Object.entries(val as Record<string, Record<string, unknown>>)) {
            if (!rec || typeof rec !== 'object') continue;
            const job = jobFromClosedFirebaseRecord(key, rec, companyId);
            if (!job) continue;
            next.set(job.id, { job, rec });
          }
        }
        allbookingsById = next;
        mergeAndSet();
      }),
      onValue(ref(db, `completedJobs/${companyId}`), (snap) => {
        const next = new Map<number, Record<string, unknown>>();
        const val = snap.val();
        if (val && typeof val === 'object') {
          for (const [key, rec] of Object.entries(val as Record<string, Record<string, unknown>>)) {
            if (!rec || typeof rec !== 'object') continue;
            if (!isClosedJobRecord(rec)) continue;
            const id = parseInt(String(rec.bookingId ?? rec.BookingId ?? key), 10);
            if (!id) continue;
            next.set(id, rec);
          }
        }
        completedById = next;
        mergeAndSet();
      }),
    ];

    return () => {
      for (const u of unsubs) u();
      allbookingsById = new Map();
      completedById = new Map();
    };
  }, [companyId, enabled]);

  return closed;
}
