import { create } from 'zustand';
import type { CompanySettings } from '@/types/booking';
import {
  type DispatchThemeId,
  initThemeFromStorage,
  nextTheme,
  persistTheme,
} from '@/lib/theme';
import { playNotificationSound, type NotifySoundKind } from '@/lib/notifySound';

export type ModalId =
  | 'createJob'
  | 'jobDetail'
  | 'closedJobDetail'
  | 'driverDetail'
  | 'messages'
  | 'closedJobs'
  | 'searchJobs'
  | 'alarms'
  | 'suspended'
  | 'acc'
  | 'emergency'
  | null;

export interface ToastItem {
  id: string;
  type: 'info' | 'success' | 'warning' | 'error';
  title: string;
  message?: string;
  category?: NotificationCategory;
  /** When true, toast does not increase bell notification count. */
  skipNotificationCount?: boolean;
  /** Auto-dismiss duration in ms (defaults to 3000). */
  durationMs?: number;
  /** Optional click handler; when set the toast becomes clickable. */
  onClick?: () => void;
}

export type NotificationCategory =
  | 'job_created'
  | 'job_cancelled'
  | 'job_updated'
  | 'job_accepted'
  | 'job_recalled'
  | 'no_show'
  | 'driver_online'
  | 'new_booking'
  | 'sos_alert'
  | 'general';

export interface NotificationItem {
  id: string;
  type: ToastItem['type'];
  title: string;
  message?: string;
  category: NotificationCategory;
  read: boolean;
  createdAt: number;
}

function inferCategory(t: Omit<ToastItem, 'id'>): NotificationCategory {
  if (t.category) return t.category;
  const hay = `${t.title} ${t.message ?? ''}`.toLowerCase();
  if (hay.includes('sos alert')) return 'sos_alert';
  if (hay.includes('no show')) return 'no_show';
  if (hay.includes('job accepted')) return 'job_accepted';
  if (hay.includes('job recalled')) return 'job_recalled';
  if (hay.includes('cancel')) return 'job_cancelled';
  if (hay.includes('updated') || hay.includes('edit')) return 'job_updated';
  if (hay.includes('new booking')) return 'new_booking';
  if (hay.includes('booked') || hay.includes('created') || hay.includes('job #')) {
    if (hay.includes('new job')) return 'new_booking';
    return 'job_created';
  }
  if (hay.includes('driver') && hay.includes('online')) return 'driver_online';
  if (hay.includes('app') || hay.includes('web') || hay.includes('hail')) return 'new_booking';
  return 'general';
}

function soundForToast(t: Omit<ToastItem, 'id'>): NotifySoundKind {
  if (t.title.toUpperCase().includes('DISPATCH NOW')) return 'alert';
  if (t.category) {
    if (t.category === 'job_created') return 'job_created';
    if (t.category === 'job_updated') return 'job_updated';
    if (t.category === 'job_cancelled') return 'job_cancelled';
    if (t.category === 'job_accepted') return 'job_created';
    if (t.category === 'job_recalled') return 'job_updated';
    if (t.category === 'no_show') return 'alert';
    if (t.category === 'sos_alert') return 'alert';
    if (t.category === 'driver_online') return 'driver_online';
    if (t.category === 'new_booking') return 'new_booking';
    return 'general';
  }
  if (t.type === 'error') return 'error';
  if (t.type === 'warning') return 'alert';
  return 'general';
}

interface UiStore {
  theme: DispatchThemeId;
  openModal: ModalId;
  modalJobId: number | null;
  modalDriverId: string | null;
  /** Bumped when toast/header opens Messages for a specific driver thread. */
  messagesFocusNonce: number;
  notificationCount: number;
  messageUnreadCount: number;
  notifications: NotificationItem[];
  toasts: ToastItem[];
  routeDrawing: boolean;
  billingBanner: string | null;
  mapTraffic: boolean;
  mapZones: boolean;
  mapVisible: boolean;
  mapFullscreen: boolean;
  mapPoppedOut: boolean;
  emergency: SosEmergency | null;
  emergencyQueue: SosEmergency[];
  settings: CompanySettings | null;
  routePreview: { pick: { lat: number; lng: number }; drop?: { lat: number; lng: number } } | null;
  mapInstance: google.maps.Map | null;
  setRoutePreview: (r: UiStore['routePreview']) => void;
  setMapInstance: (map: google.maps.Map | null) => void;
  setTheme: (t: DispatchThemeId) => void;
  cycleTheme: () => void;
  openModalWith: (m: ModalId, opts?: { jobId?: number; driverId?: string }) => void;
  openMessagesForDriver: (driverId: string) => void;
  closeModal: () => void;
  addToast: (t: Omit<ToastItem, 'id'>) => void;
  removeToast: (id: string) => void;
  dismissNotification: (id: string) => void;
  clearAllNotifications: () => void;
  setRouteDrawing: (v: boolean) => void;
  setNotificationCount: (n: number) => void;
  setMessageUnreadCount: (n: number) => void;
  setBillingBanner: (msg: string | null) => void;
  setMapTraffic: (v: boolean) => void;
  setMapZones: (v: boolean) => void;
  setMapVisible: (v: boolean) => void;
  setMapFullscreen: (v: boolean) => void;
  setMapPoppedOut: (v: boolean) => void;
  setEmergency: (e: UiStore['emergency']) => void;
  setEmergencyQueue: (q: UiStore['emergencyQueue']) => void;
  setSettings: (s: CompanySettings | null) => void;
}

export interface SosResponder {
  driverId: string;
  name: string;
  vehicleNo: string;
  respondedAt: number;
  state: string;
}

export interface SosEmergency {
  incidentId: string;
  sosId: string;
  driverName: string;
  driverPhone: string;
  vehicle: string;
  lat: number;
  lng: number;
  locationAddress: string;
  time: string;
  status: 'active' | 'acknowledged';
  dispatchMessage?: string;
  responders: SosResponder[];
  triggeredAt: number;
}

export const useUiStore = create<UiStore>((set, get) => ({
  theme: initThemeFromStorage(),
  openModal: null,
  modalJobId: null,
  modalDriverId: null,
  messagesFocusNonce: 0,
  notificationCount: 0,
  messageUnreadCount: 0,
  notifications: [],
  toasts: [],
  routeDrawing: false,
  billingBanner: null,
  mapTraffic: true,
  mapZones: true,
  mapVisible: localStorage.getItem('bw_map_visible') !== 'false',
  mapFullscreen: false,
  mapPoppedOut: false,
  emergency: null,
  emergencyQueue: [],
  settings: null,
  routePreview: null,
  mapInstance: null,
  setTheme: (t) => {
    persistTheme(t);
    set({ theme: t });
  },
  cycleTheme: () => {
    const t = nextTheme(get().theme);
    persistTheme(t);
    set({ theme: t });
  },
  openModalWith: (m, opts) =>
    set({ openModal: m, modalJobId: opts?.jobId ?? null, modalDriverId: opts?.driverId ?? null }),
  openMessagesForDriver: (driverId) =>
    set((s) => ({
      openModal: 'messages',
      modalJobId: null,
      modalDriverId: driverId,
      messagesFocusNonce: s.messagesFocusNonce + 1,
    })),
  closeModal: () =>
    set({ openModal: null, modalJobId: null, modalDriverId: null, routePreview: null }),
  addToast: (t) => {
    const id = `${Date.now()}-${Math.random()}`;
    const category = inferCategory(t);
    playNotificationSound(soundForToast({ ...t, category }));
    const skipBell = !!t.skipNotificationCount;
    const notification: NotificationItem = {
      id,
      type: t.type,
      title: t.title,
      message: t.message,
      category,
      read: false,
      createdAt: Date.now(),
    };
    set((s) => ({
      notifications: skipBell ? s.notifications : [notification, ...s.notifications].slice(0, 100),
      toasts: [...s.toasts, { ...t, id, category }].slice(-2),
      notificationCount: skipBell ? s.notificationCount : s.notificationCount + 1,
    }));
    setTimeout(() => {
      get().removeToast(id);
    }, t.durationMs ?? 3000);
  },
  removeToast: (id) => set((s) => ({ toasts: s.toasts.filter((x) => x.id !== id) })),
  dismissNotification: (id) =>
    set((s) => {
      const target = s.notifications.find((n) => n.id === id);
      const next = s.notifications.filter((n) => n.id !== id);
      return {
        notifications: next,
        notificationCount: Math.max(0, s.notificationCount - (target && !target.read ? 1 : 0)),
      };
    }),
  clearAllNotifications: () => set({ notifications: [], notificationCount: 0 }),
  setRouteDrawing: (v) => set({ routeDrawing: v }),
  setNotificationCount: (n) => set({ notificationCount: n }),
  setMessageUnreadCount: (n) => set({ messageUnreadCount: Math.max(0, n) }),
  setBillingBanner: (msg) => set({ billingBanner: msg }),
  setMapTraffic: (v) => set({ mapTraffic: v }),
  setMapZones: (v) => set({ mapZones: v }),
  setMapVisible: (v) => {
    localStorage.setItem('bw_map_visible', v ? 'true' : 'false');
    set({ mapVisible: v });
  },
  setMapFullscreen: (v) => set({ mapFullscreen: v }),
  setMapPoppedOut: (v) => set({ mapPoppedOut: v }),
  setEmergency: (e) => set({ emergency: e }),
  setEmergencyQueue: (q) => set({ emergencyQueue: q }),
  setSettings: (s) => set({ settings: s }),
  setRoutePreview: (r) => set({ routePreview: r }),
  setMapInstance: (map) => set({ mapInstance: map }),
}));
